package com.example.demo.service; import com.example.demo.model.Employee; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.slf4j.*; @Service public class EmployeeService { @Autowired private Employee employee; private static final Logger log=LoggerFactory.getLogger(EmployeeService.class); public void displayEmployeeDetails(){log.info("Fetching employee information via EmployeeService...");log.debug("Employee instance details: "+employee);System.out.println(employee);} }